    el.dispatchEvent(new MouseEvent('mousedown', { ...base, detail: d }));
    el.dispatchEvent(new PointerEvent('pointerup', { ...base, pointerId: 1, isPrimary: true, button: 0, detail: d }));
    el.dispatchEvent(new MouseEvent('mouseup', { ...base, detail: d }));
    el.dispatchEvent(new MouseEvent('click', { ...base, detail: d }));
